{"content":"import { expect, test, beforeAll } from "bun:test";
import { db, initDb } from "../db/connection";
import { existsSync } from "node:fs";

test("Database initialization", () => {
  // Run init
  initDb();

  // Check if file exists
  expect(existsSync("data/moment-diary.db")).toBe(true);

  // Check table structures
  const tables = db.query("SELECT name FROM sqlite_master WHERE type='table'").all() as { name: string }[];
  const tableNames = tables.map(t => t.name);

  expect(tableNames).toContain("users");
  expect(tableNames).toContain("sessions");
  expect(tableNames).toContain("diary_entries");
  expect(tableNames).toContain("tags");
  expect(tableNames).toContain("diary_tags");
});
